          <div class="btn" @click="goSetPwd">去设置提现密码</div>
          <div class="tip-close" @click="drawpasswdflagShow=false" />
        </div>
      </van-popup>
    </div>
    <div class="tip-pop">
      <van-popup v-model="isScaning" class="scan-pop" close-icon="close" closeable>
        <div v-if="isScaning" class="reader-box">
