</template>
<script>
import TitleLine from '../modules/TitleLine'
import { webDrawIndex, doWebWithdraw, drawinfos, sendDraw, getRgHuione, getRgBaiyi } from '@/api/user'
import usdtIcon from '@/assets/portal/usdt_icon.png'
import hwApp from '@/assets/portal/汇旺转账2.webp'
import hwWallet from '@/assets/portal/汇旺转账2.webp'
import byWallet from '@/assets/portal/佰易钱包.webp'
import scanBg from '@/assets/portal/img_插图.webp'
import { nextTick } from 'vue'
import { Html5Qrcode, Html5QrcodeScanner } from 'html5-qrcode'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      html5Qrcode: null,
      html5QrcodeScanner: null,
      isScaning: false,
      arrShow: false,
      title: this.$t('txym.txym01'),
      boturl: '',
      typeList: [{ label: this.$t('txym.txym02'), value: 0 }, { label: this.$t('txym.txym03'), value: 1 }
      // { label: '玩家查询', value: 2 }, { label: '返佣比例', value: 3 }, { label: '代理介绍', value: 4 }
      ],
      tabList: [
        { label: this.$t('czym.czym04'), value: 0 },
        { label: this.$t('czym.czym05'), value: 1 }
        // { label: this.$t('czym.czym06'), value: 2 }
      ],
      currentIndex: 0,
      tabColor: 0,
      oldTabColor: 0,
      currencyType: 0,
      blockChain: 0,
      payMode: 0,
      wallet: '',
      hwName: '',
      addressPlaceholder: this.$t('txym.txym211'),
      hwNamePlaceholder: this.$t('txym.txym22'),
      hwCodePlaceholder: this.$t('txym.txym24'),
      phoneAreaPlaceholder: this.$t('txym.txym62'),
      phonePlaceholder: this.$t('txym.txym64'),
      hwCode: '',
      phoneArea: '',
      phoneNumber: '',
      byName: '',
      byCode: '',
      byNamePlaceholder: this.$t('txym.txym36'),
      byCodePlaceholder: this.$t('txym.txym38'),
      needmons: '',
      umons: '',
      monsInput: '',
      password: '',
      currencyTypeOption: [
        { text: 'USDT', value: 0, icon: usdtIcon }
      ],
      blockChainOption: [
        { text: 'TRC-20', value: 0 }
        // { text: 'ERC-20', value: 1 }
      ],
      walletOption: [],
      drawpasswdflag: false,
      drawpasswdflagShow: false,
      loading: false,
      disabled: false,
      payModeList: [{ payMode: this.$t('txym.txym59'), index: 0, imgUrl: hwApp }, { payMode: this.$t('txym.txym60'), index: 1, imgUrl: byWallet }],
      drawstatus: '',
      intervalGetDom: null
    }
  },
  watch: {
    // 监听 activeIndex 的变化
    tabColor(newVal, oldVal) {
      // oldVal: 切换前的旧索引
      // newVal: 切换后的新索引
      this.oldTabColor = oldVal
    },
    isScaning(newVal) {
      if (!newVal) {
        this.stopScan()
        if (this.intervalGetDom) {
          clearInterval(this.intervalGetDom)
          this.intervalGetDom = null
        }
      }
    }
  },
  created() {
    // drawinfos().then(res => {
    //   this.boturl = res.boturl
    // })
    // webDrawIndex().then(res => {})
    webDrawIndex().then(res => {
      this.boturl = res.boturl
      this.walletOption = res.datalist.map(item => {
        return { text: item.usdturl, value: item.usdturl }
      })
      // this.wallet = this.walletOption.length > 0 ? this.walletOption[0].value : ''
      this.needmons = res.needmons
      this.umons = res.umons
      this.drawpasswdflag = res.drawpasswdflag === '0'
      this.drawpasswdflagShow = res.drawpasswdflag === '0'
      // this.hwName = res.txinfohuione.split(',')[0]
      // // this.hwCode = res.txinfohuione.split(',')[1]
      // this.phoneArea = res.txinfohuione.split(',')[1]
      // this.phoneNumber = res.txinfohuione.split(',')[2]
      this.hwName = res.txinfohuionename
      this.phoneArea = res.txinfohuionearea
      this.phoneNumber = res.txinfohuionphone
      this.byName = res.txinfobaiyi.split(',')[0]
      this.byCode = res.txinfobaiyi.split(',')[1]
      this.drawstatus = res.drawstatus
      this.hwNamePlaceholder = this.$t('txym.txym22') + res.hwname + '）'
      this.hwCodePlaceholder = this.$t('txym.txym24') + res.hwcode + '）'
      this.byNamePlaceholder = this.$t('txym.txym36') + res.byname + '）'
      this.byCodePlaceholder = this.$t('txym.txym38') + res.bycode + '）'
      this.phoneAreaPlaceholder = this.$t('txym.txym62') + res.hwarea + '）'
      this.phonePlaceholder = this.$t('txym.txym64') + res.hwphone + '）'
      const arr = []
      const subarr = []
      // res.czlist.forEach(element => {
      //   const ele = this.tabList.find(item => item.value === Number(element.type))
      //   ele.label = element.name
      //   arr.push(ele)
      //   if(element.type==='2'){ //汇旺-佰易
      //     element.types.forEach(item => {
      //       const subEle = this.payModeList.find(obj => obj.index === Number(item.type))
      //       subarr.push(subEle)
      //     })
      //   }
      // }) res.txlevel1&&
      res.txlevel1 && res.txlevel1.split(';').forEach((element, index) => {
        const ele = this.tabList.find(item => item.label === element)
        arr.push(ele)
        if (element === this.$t('czym.czym05')) { // 汇旺-佰易
          res.txlevel2.split(';')[index].split(',').forEach(item => {
            const subEle = this.payModeList.find(obj => obj.payMode === item)
            subarr.push(subEle)
          })
        }
      })
      this.payModeList = subarr
      this.tabList = arr
    })
  },
  mounted() {
  },
  beforeDestroy() {
    if (this.intervalGetDom) {
      clearInterval(this.intervalGetDom)
      this.intervalGetDom = null
    }
    this.stopScan()
  },
  methods: {
    onScanSuccess(decodedText, decodedResult) {
      // Handle on success condition with the decoded text or result.
      console.log(`Scan result: ${decodedText}`, decodedResult)
      this.wallet = decodedText
      this.html5QrcodeScanner.clear()
      this.isScaning = false
    },
    onScanError(errorMessage) {
      // this.$toast.fail(errorMessage)
      // handle on error condition, with error message
    },
    async openQrcode() {
      this.isScaning = true
      await this.$nextTick()
      this.html5QrcodeScanner = new Html5QrcodeScanner(
        'reader', { fps: 10, qrbox: { width: 300, height: 300 }})
      this.html5QrcodeScanner.render(this.onScanSuccess, this.onScanError)
      // const scanState = this.html5QrcodeScanner.getState()
      // debugger
      const eleArr = document.querySelectorAll('img')
      debugger
      await this.$nextTick()
      eleArr.forEach(item => {
        if (item.alt.includes('Camera based scan')) {
          item.src = scanBg
        } else if (item.alt.includes('Info icon')) {
          item.style.display = 'none'
        }
      })

      if (this.intervalGetDom) {
        clearInterval(this.intervalGetDom)
        this.intervalGetDom = null
      }
      this.intervalGetDom = setInterval(() => {
        const dom = document.getElementById('html5-qrcode-button-camera-permission')
        if (dom) {
          dom.innerHTML = '获取相机权限'
        }
        const eleArr = document.querySelectorAll('img')
        eleArr.forEach(item => {
          if (item.alt.includes('Camera based scan')) {
            item.src = scanBg
            item.style.height = '137px'
            item.style.width = '120px'
            clearInterval(this.intervalGetDom)
          }
        })
        // const dom1 = document.getElementById('html5-qrcode-button-camera-start')
        // if (dom1) {
        //   dom1.innerHTML = '开始扫码'
        // }
        // const dom2 = document.getElementById('html5-qrcode-button-camera-start')
        // if (dom2) {
        //   dom1.innerHTML = '关闭'
        // }
      }, 100)
    },
    // methods方法
    async openQrcode1() {
      this.isScaning = true
      await this.$nextTick()
      Html5Qrcode.getCameras().then((devices) => {
        if (devices && devices.length) {
          this.html5Qrcode = new Html5Qrcode('reader')
          this.html5Qrcode.start(
            {
              facingMode: 'environment'
            },
            {
              focusMode: 'continuous', // 设置连续聚焦模式
              fps: 5, // 设置扫码识别速度
              qrbox: 280 // 设置二维码扫描框大小
            },
            (decodeText, decodeResult) => {
              if (decodeText) { // 这里decodeText就是通过扫描二维码得到的内容
                debugger
                this.wallet = decodeText
                console.log('Decoded text from QRCode:', decodeText)
                // this.action(decodeText)  //对二维码逻辑处理
                this.stopScan() // 关闭扫码功能
              }
            },
            (err) => {
              // console.log(err);  //错误信息
            }
          )
        }
      })
    },
    stopScan() {
      console.log('停止扫码')
      debugger
      if (this.html5QrcodeScanner) {
        this.html5QrcodeScanner.clear()
      }
      this.isScaning = false
    },
    async onSelect(id) {
      this.payMode = id
    },
    getSubClass(value, label) {
      this.currentIndex = value
      localStorage.setItem('currentIndex', value)
    },
    async getTypeClass(value, label) {
      this.tabColor = value
      if (value === 2) {
        this.$toast.fail(this.$t('home.sy42'))
        this.$nextTick(() => {
          this.tabColor = this.oldTabColor
        })
      }
    },
    goMore() {
      this.$router.push({ path: '/rechargeRecord', query: { type: 1 }})
    },
    goSetPwd() {
      this.$router.push({ path: '/setReflectPsd', query: { type: 1 }})
    },
    open() {
      window.open(this.boturl)
      sendDraw()
      // window.open('https://t.me/RR666_bot')
    },
    toAddAddress() {
      this.$router.push({
        path: '/addWalletAress'
      })
    },
    async onChoose(id) {
      this.tabColor = id
    },
    onSubmit() {
      this.loading = true
      this.disabled = true
      const param = {
        uidto: this.tabColor === 0 ? this.wallet : (this.payMode === 0 ? (this.hwName + ',' + this.phoneArea + ',' + this.phoneNumber) : (this.byName + ',' + this.byCode)),
        mons: this.monsInput,
        type: Number(this.tabColor) === 0 ? 1 : this.payMode === 0 ? 2 : 6,
        drawpwd: this.password

      }
      doWebWithdraw(param).then(res => {
        this.$toast('提现成功')
        this.umons = res.umons
        this.monsInput = ''
        this.password = ''
        this.loading = false
        this.disabled = false
      }).catch((e) => {
        this.$toast.fail(e.message)
      })
        .finally(() => {
          this.loading = false
          this.disabled = false
        })
    },
    onFailed(errorInfo) {
      console.log('failed', errorInfo)
      this.$toast(errorInfo.errors[0].message)
    }
  }
}
</script>
